import React, { useState, useEffect } from 'react';
import { Table, Card, Button, DatePicker, Space, Tag, message } from 'antd';
import { DownloadOutlined, ReloadOutlined } from '@ant-design/icons';
import api from '../../services/api';
import dayjs from 'dayjs';

const { RangePicker } = DatePicker;

/**
 * ThresholdAuditTable - Component to display threshold audit logs
 * Generated by Copilot
 */
const ThresholdAuditTable = () => {
  const [loading, setLoading] = useState(false);
  const [auditLogs, setAuditLogs] = useState([]);
  const [dateRange, setDateRange] = useState(null);

  useEffect(() => {
    loadAuditLogs();
  }, []);

  const loadAuditLogs = async (from = null, to = null) => {
    setLoading(true);
    try {
      const params = {};
      if (from) params.from = from;
      if (to) params.to = to;

      const response = await api.get('/api/v1/admin/thresholds/audit', { params });
      setAuditLogs(response.data.logs || []);
    } catch (error) {
      message.error('加载审计日志失败: ' + (error.response?.data?.error || error.message));
    } finally {
      setLoading(false);
    }
  };

  const handleDateRangeChange = (dates) => {
    setDateRange(dates);
    if (dates && dates[0] && dates[1]) {
      const from = dates[0].toISOString();
      const to = dates[1].toISOString();
      loadAuditLogs(from, to);
    } else {
      loadAuditLogs();
    }
  };

  const handleExport = async () => {
    try {
      const params = {};
      if (dateRange && dateRange[0] && dateRange[1]) {
        params.from = dateRange[0].toISOString();
        params.to = dateRange[1].toISOString();
      }

      const response = await api.get('/api/v1/admin/thresholds/audit/export', {
        params,
        responseType: 'blob'
      });

      // Create download link
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `threshold_audit_${Date.now()}.csv`);
      document.body.appendChild(link);
      link.click();
      link.remove();

      message.success('导出成功');
    } catch (error) {
      message.error('导出失败: ' + (error.response?.data?.error || error.message));
    }
  };

  const getActionTag = (action) => {
    const actionConfig = {
      draft_created: { color: 'blue', text: '创建草稿' },
      publish: { color: 'green', text: '发布' },
      export: { color: 'purple', text: '导出' },
      archive: { color: 'default', text: '归档' }
    };
    const config = actionConfig[action] || { color: 'default', text: action };
    return <Tag color={config.color}>{config.text}</Tag>;
  };

  const columns = [
    {
      title: 'ID',
      dataIndex: 'id',
      key: 'id',
      width: 80
    },
    {
      title: '操作',
      dataIndex: 'action',
      key: 'action',
      width: 120,
      render: (action) => getActionTag(action)
    },
    {
      title: '操作者ID',
      dataIndex: 'actor_id',
      key: 'actor_id',
      width: 100
    },
    {
      title: 'IP地址',
      dataIndex: 'actor_ip',
      key: 'actor_ip',
      width: 150
    },
    {
      title: '配置ID',
      dataIndex: 'profile_id',
      key: 'profile_id',
      width: 100
    },
    {
      title: '版本',
      dataIndex: 'version',
      key: 'version',
      width: 80
    },
    {
      title: '创建时间',
      dataIndex: 'created_at',
      key: 'created_at',
      render: (value) => new Date(value).toLocaleString('zh-CN')
    }
  ];

  return (
    <Card 
      title="阈值审计日志" 
      bordered={false}
      extra={
        <Space>
          <RangePicker 
            onChange={handleDateRangeChange}
            format="YYYY-MM-DD"
          />
          <Button 
            icon={<ReloadOutlined />} 
            onClick={() => loadAuditLogs()}
          >
            刷新
          </Button>
          <Button 
            icon={<DownloadOutlined />} 
            onClick={handleExport}
          >
            导出CSV
          </Button>
        </Space>
      }
    >
      <Table
        columns={columns}
        dataSource={auditLogs}
        loading={loading}
        rowKey="id"
        pagination={{ pageSize: 20 }}
        size="small"
        expandable={{
          expandedRowRender: (record) => (
            <div style={{ padding: '10px' }}>
              <h4>操作详情</h4>
              <p><strong>User Agent:</strong> {record.actor_user_agent || '-'}</p>
              {record.before_payload && (
                <div>
                  <strong>变更前:</strong>
                  <pre style={{ background: '#f5f5f5', padding: '10px', marginTop: '5px' }}>
                    {JSON.stringify(record.before_payload, null, 2)}
                  </pre>
                </div>
              )}
              {record.after_payload && (
                <div style={{ marginTop: '10px' }}>
                  <strong>变更后:</strong>
                  <pre style={{ background: '#f5f5f5', padding: '10px', marginTop: '5px' }}>
                    {JSON.stringify(record.after_payload, null, 2)}
                  </pre>
                </div>
              )}
            </div>
          )
        }}
      />
    </Card>
  );
};

export default ThresholdAuditTable;
